    cursor: pointer
}

button {
    padding: 0
}

button,input,optgroup,select,textarea {
    font: inherit
}

b,strong,dfn {
    font-weight: var(--slds-g-font-weight-7)
}

mark {
    background-color: var(--slds-g-color-palette-yellow-90);
